82	// The function `makeBufferWithLayout` creates a new Buffer object based on the
83	// given buffer and layout. It handles remapping of buffer variables, adjusts
84	// the storage scope if needed (e.g., from "local.fragment" to "local"), and
85	// computes the output shape according to the layout. For shared memory buffers,
86	// it also handles replication if the buffer's extent is larger than the
87	// layout's extent.
88	class LayoutRemapRewriter : public arith::IRMutatorWithAnalyzer {
89	public:
90	  static Stmt Substitute(Stmt stmt, Map<Buffer, Layout> layout_remap) {
91	    arith::Analyzer analyzer;
92	    LayoutRemapRewriter substituter(&analyzer);
93	    substituter.layout_remap_ = std::move(layout_remap);
94	    return substituter.VisitStmt(stmt);
95	  }
96	
97	private:
98	  using arith::IRMutatorWithAnalyzer::IRMutatorWithAnalyzer;
99	
100	  Stmt VisitStmt_(const BlockNode *op) final {
101	    auto block = Downcast<Block>(arith::IRMutatorWithAnalyzer::VisitStmt_(op));
102	    if (op->annotations.count(attr::kLayoutMap)) {
103	      block.CopyOnWrite()->annotations.Set(attr::kLayoutMap, layout_remap_);
104	    }
105	    return block;
106	  }
107	
108	  Map<Buffer, Layout> layout_remap_;
109	};
