275	  int CheckAndGetBufferRowSize(const Buffer &buffer) {
276	    CHECK(buffer->shape.size() >= 2)
277	        << "The dimension of Buffer \"" << buffer->name << "\" with shape "
278	        << buffer->shape << " should be at least 2";
279	
280	    auto dim = buffer->shape.size();
281	    auto buffer_row_size = buffer->shape[dim - 1].as<IntImmNode>()->value;
282	    return buffer_row_size;
283	  }
284	
285	  struct AccessPtrResult {
286	    PrimExpr expr;
287	    bool rewritten{false};
288	  };
289	
290	  AccessPtrResult
291	  HandleAccessPtrAndOffset(const PrimExpr &access_ptr,
292	                           const Optional<PrimExpr> &offset = std::nullopt,
293	                           DataType dtype = DataType::Int(32)) {
294	    AccessPtrResult result{access_ptr, false};
295	    // The 2th arg of T.tvm_access_ptr call is offset, we set it to 0 and
296	    // accumulate it to smem_offset
297	    CHECK(access_ptr->IsInstance<CallNode>())
298	        << "Invalid access ptr for permuted layout: " << access_ptr;
299	    auto access_ptr_call = Downcast<Call>(access_ptr);
300	    if (access_ptr_call->op.same_as(builtin::tvm_access_ptr())) {
301	      LOG(FATAL) << "Transformation for tvm_access_ptr is not implemented yet";
302	    } else if (access_ptr_call->op.same_as(builtin::address_of())) {
303	      Optional<PrimExpr> resolved = ResolveBufferLoad(access_ptr_call->args[0]);
304	      ICHECK(resolved.defined())
305	          << "Invalid access op for permuted layout: " << access_ptr;
306	      PrimExpr load_expr = resolved.value();
307	      if (!load_expr.same_as(access_ptr_call->args[0])) {
308	        auto node = access_ptr_call.CopyOnWrite();
309	        node->args.Set(0, load_expr);
310	        access_ptr_call =
311	            Call(access_ptr_call->dtype, access_ptr_call->op, {load_expr},
312	                 access_ptr_call->annotations, access_ptr_call->span);
313	      }
314	      BufferLoad load = Downcast<BufferLoad>(access_ptr_call->args[0]);
315	      Array<PrimExpr> indices = load->indices;
316	      Array<PrimExpr> old_shape = load->buffer->shape;
317	
318	      CHECK_EQ(indices.size(), old_shape.size())
319	          << "Indices size and shape size must match for general N-dimensional "
320	             "buffer "
321	          << "but got indices size: " << indices.size()
322	          << " and shape size: " << old_shape.size();
323	
324	      PrimExpr elem_offset = 0;
325	      PrimExpr stride = 1;
326	
327	      for (int i = static_cast<int>(old_shape.size()) - 1; i >= 0; --i) {
328	        elem_offset += indices[i] * stride;
329	        stride *= old_shape[i];
330	      }
331	
332	      PrimExpr smem_offset =
333	          elem_offset + (offset.defined() ? offset.value() : 0);
334	
335	      Buffer remap_key = FindRemapBuffer(load->buffer).value_or(load->buffer);
336	      Optional<Layout> layout = FindLayout(remap_key);
337	      if (!layout.defined() || !buffer_map_.count(remap_key->data)) {
338	        return result;
339	      }
340	      auto new_buffer = buffer_remap_.count(remap_key)
341	                            ? buffer_remap_[remap_key]
342	                            : load->buffer;
343	      auto new_shape = new_buffer->shape;
344	
345	      auto buffer_map_iter = buffer_map_.find(Downcast<Var>(remap_key->data));
346	
347	      int buffer_row_size = CheckAndGetBufferRowSize(buffer_map_iter->second);
348	      (void)buffer_row_size;
349	
350	      // Convert offset to target-dimension, reindex it and convert it back
351	      Array<PrimExpr> multi_dim_indices;
352	      PrimExpr remaining_offset = smem_offset;
353	
354	      for (int i = static_cast<int>(old_shape.size()) - 1; i >= 0; --i) {
355	        multi_dim_indices.insert(multi_dim_indices.begin(),
356	                                 floormod(remaining_offset, old_shape[i]));
357	        remaining_offset = floordiv(remaining_offset, old_shape[i]);
358	      }
359	
360	      auto forward_indices = layout.value()->Forward(multi_dim_indices);
361	      PrimExpr new_offset = 0;
362	      PrimExpr stride_offset = 1;
363	      for (int i = static_cast<int>(new_shape.size()) - 1; i >= 0; --i) {
364	        new_offset += forward_indices[i] * stride_offset;
365	        stride_offset *= new_shape[i];
366	      }
367	      new_offset = analyzer_->Simplify(new_offset);
368	
369	      Array<PrimExpr> new_indices;
370	      for (int i = static_cast<int>(new_shape.size()) - 1; i >= 0; --i) {
371	        new_indices.insert(new_indices.begin(),
372	                           floormod(new_offset, new_shape[i]));
373	        new_offset = floordiv(new_offset, new_shape[i]);
374	      }
375	
376	      Array<PrimExpr> new_args = {BufferLoad(new_buffer, new_indices)};
377	      if (buffer_remap_.count(remap_key)) {
378	        layout_remap_.Set(new_buffer, layout.value());
379	      }
380	      result.rewritten = true;
381	      result.expr = Call(access_ptr_call->dtype, access_ptr_call->op, new_args,
382	                         access_ptr_call->annotations, access_ptr_call->span);
383	      return result;
384	    } else {
385	      LOG(FATAL) << "Invalid access op for permuted layout: " << access_ptr;
386	    }
387	
388	    return result;
389	  }
390	
391	  Optional<PrimExpr> ResolveBufferLoad(const PrimExpr &expr) const {
392	    if (expr->IsInstance<BufferLoadNode>()) {
393	      return expr;
394	    }
395	    if (const auto *var_node = expr.as<VarNode>()) {
396	      Var var = tvm::ffi::GetRef<Var>(var_node);
397	      auto it = let_bindings_.find(var);
398	      if (it != let_bindings_.end()) {
399	        return it->second;
400	      }
401	    }
402	    return Optional<PrimExpr>();
403	  }
404	
405	  Optional<Buffer> FindRemapBuffer(const Buffer &buffer) const {
406	    if (buffer_remap_.count(buffer)) {
407	      return buffer;
408	    }
409	    auto it = buffer_map_.find(buffer->data);
410	    if (it != buffer_map_.end() && buffer_remap_.count(it->second)) {
411	      return it->second;
412	    }
413	    for (const auto &kv : buffer_remap_) {
414	      if (kv.first->data.same_as(buffer->data)) {
415	        return kv.first;
416	      }
417	      if (kv.first->name == buffer->name) {
418	        return kv.first;
419	      }
420	    }
421	    return Optional<Buffer>();
422	  }
423	
424	  Optional<Layout> FindLayout(const Buffer &buffer) const {
425	    if (layout_map_.count(buffer)) {
426	      return layout_map_[buffer];
427	    }
428	    auto it = buffer_map_.find(buffer->data);
429	    if (it != buffer_map_.end() && layout_map_.count(it->second)) {
430	      return layout_map_[it->second];
431	    }
432	    for (const auto &kv : layout_map_) {
433	      if (kv.first->data.same_as(buffer->data)) {
434	        return kv.second;
435	      }
436	      if (kv.first->name == buffer->name) {
437	        return kv.second;
438	      }
439	    }
440	    return Optional<Layout>();
441	  }
442	
443	  PrimExpr VisitExpr_(const tir::CallNode *op) final {
444	    if ((!has_tma_) && (op->op.same_as(tl::tma_load()) ||
445	                        op->op.same_as(tl::tma_load_im2col()) ||
446	                        op->op.same_as(tl::tma_store()))) {
447	      has_tma_ = true;
448	    }
449	    Array<RelaxExpr> ptx_instructions = {builtin::ptx_ldmatrix(),
450	                                         builtin::mma_store()};
451	
452	    if (std::find(ptx_instructions.begin(), ptx_instructions.end(), op->op) ==
453	        ptx_instructions.end()) {
454	      auto call = Downcast<Call>(IRMutatorWithAnalyzer::VisitExpr_(op));
455	      return call;
456	    } else {
457	      is_ptx_ = true;
458	    }
459	    // Rewrite from/to shared or shared.dyn to/from local
460	    auto call = Downcast<Call>(IRMutatorWithAnalyzer::VisitExpr_(op));
461	    if (call->op.same_as(builtin::ptx_ldmatrix())) {
462	      // form: T.ptx_ldmatrix(..., smem_ptr, smem_offset)
463	      // smem_ptr: T.tvm_access_ptr(ptype, data, offset, extent, rw_mask)
464	      // or T.address_of(buffer, offset)
465	      PrimExpr access_ptr = call->args[5];
466	      PrimExpr smem_offset = call->args[6];
467	      Call address_of_call = Downcast<Call>(access_ptr);
468	      if (!address_of_call->op.same_as(builtin::address_of())) {
469	        LOG(FATAL) << "Invalid access ptr for permuted layout: " << access_ptr;
470	      }
471	      Optional<PrimExpr> resolved = ResolveBufferLoad(address_of_call->args[0]);
472	      ICHECK(resolved.defined())
473	          << "Invalid address_of argument for permuted layout: "
474	          << address_of_call->args[0];
475	      PrimExpr load_expr = resolved.value();
476	      if (!load_expr.same_as(address_of_call->args[0])) {
477	        auto call_node = call.CopyOnWrite();
478	        call_node->args.Set(5, Call(address_of_call->dtype, address_of_call->op,
479	                                    {load_expr}, address_of_call->annotations,
480	                                    address_of_call->span));
481	        address_of_call = Downcast<Call>(call->args[5]);
482	        access_ptr = call->args[5];
483	      }
484	      BufferLoad load = Downcast<BufferLoad>(address_of_call->args[0]);
485	      auto new_access_ptr =
486	          HandleAccessPtrAndOffset(access_ptr, smem_offset, call->dtype);
487	      if (new_access_ptr.rewritten) {
488	        auto new_call = call.CopyOnWrite();
489	        new_call->args.Set(5, new_access_ptr.expr);
490	        new_call->args.Set(6, IntImm(smem_offset->dtype, 0));
491	      }
492	    } else if (call->op.same_as(builtin::mma_store())) {
493	      // because we will directly store result to Buffer instead of calling
494	      // mma_store now
495	      auto access_ptr = call->args[2];
496	      auto new_access_ptr =
497	          HandleAccessPtrAndOffset(access_ptr, std::nullopt, call->dtype);
498	      if (new_access_ptr.rewritten) {
499	        auto new_call = call.CopyOnWrite();
500	        new_call->args.Set(2, new_access_ptr.expr);
501	      }
502	    } else {
503	      LOG(FATAL) << "Invalid call node: " << call;
504	    }
505	    is_ptx_ = false;
506	    return call;
507	  }
508	
509	  PrimExpr VisitExpr_(const BufferLoadNode *op) final {
510	    auto load = Downcast<BufferLoad>(IRMutatorWithAnalyzer::VisitExpr_(op));
511	    if (is_ptx_) {
512	      return load;
513	    }
514	    auto buffer = load->buffer;
515	    if (buffer_remap_.count(buffer)) {
516	      auto new_indices = layout_map_[buffer]->Forward(load->indices);
517	      auto new_buffer = buffer_remap_[load->buffer];
518	      layout_remap_.Set(new_buffer, layout_map_[load->buffer]);
519	      return BufferLoad(new_buffer, new_indices);
520	    } else if (var_remap_.count(buffer->data)) {
521	      auto new_buffer = Buffer(
522	          var_remap_[buffer->data], buffer->dtype, buffer->shape,
523	          buffer->strides, buffer->elem_offset, buffer->name,
524	          buffer->data_alignment, buffer->offset_factor, buffer->buffer_type);
525	      return BufferLoad(new_buffer, load->indices);
526	    }
527	    return load;
528	  }
529	
530	  Stmt VisitStmt_(const BufferStoreNode *op) final {
531	    auto store = Downcast<BufferStore>(IRMutatorWithAnalyzer::VisitStmt_(op));
532	    auto buffer = store->buffer;
533	    if (buffer_remap_.count(buffer)) {
534	      auto new_indices = layout_map_[buffer]->Forward(store->indices);
535	      auto new_buffer = buffer_remap_[store->buffer];
536	      layout_remap_.Set(new_buffer, layout_map_[store->buffer]);
537	      return BufferStore(new_buffer, store->value, new_indices);
538	    } else if (var_remap_.count(buffer->data)) {
539	      auto new_buffer = Buffer(
540	          var_remap_[buffer->data], buffer->dtype, buffer->shape,
541	          buffer->strides, buffer->elem_offset, buffer->name,
542	          buffer->data_alignment, buffer->offset_factor, buffer->buffer_type);
543	      return BufferStore(new_buffer, store->value, store->indices);
544	    }
545	    return store;
546	  }
547	
548	  PrimExpr VisitExpr_(const VarNode *op) final {
549	    auto var = Downcast<Var>(IRMutatorWithAnalyzer::VisitExpr_(op));
550	    if (buffer_data_to_buffer_.count(var)) {
551	      auto buffer = buffer_data_to_buffer_[var];
552	      if (buffer_remap_.count(buffer))
553	        return buffer_remap_[buffer]->data;
554	    }
555	    return var;
556	  }
557	
558	  Stmt VisitStmt_(const LetStmtNode *op) final {
559	    PrimExpr value = this->VisitExpr(op->value);
560	    bool recorded = false;
561	    if (value->IsInstance<BufferLoadNode>()) {
562	      let_bindings_[op->var] = value;
563	      recorded = true;
564	    }
565	    if (SideEffect(value) <= CallEffectKind::kPure) {
566	      analyzer_->Bind(op->var, value);
567	    }
568	    Stmt body = this->VisitStmt(op->body);
569	    if (recorded) {
570	      let_bindings_.erase(op->var);
571	    }
572	    if (value.same_as(op->value) && body.same_as(op->body)) {
573	      return tvm::ffi::GetRef<Stmt>(op);
574	    } else {
575	      auto n = this->CopyOnWrite(op);
576	      n->value = value;
577	      n->body = body;
578	      return Stmt(n);
579	    }
580	  }
581	
582	  /**
583	   * @brief Handle an Evaluate node, lowering a detected tile operator to TIR.
584	   *
585	   * This visit implementation detects whether the Evaluate node represents a
586	   * tile operator invocation (via ParseOperator). If no tile operator is found
587	   * or the call targets a global function, the node is delegated to the base
588	   * visitor.
589	   *
590	   * When a tile operator is present, the method:
591	   * - Builds a workspace-allocation callback that creates a dynamic shared
592	   * buffer named "workspace" (storage scope "shared.dyn") and returns its write
593	   *   access pointer.
594	   * - Determines thread bounds for lowering from the analyzer's constant-int
595	   *   information for thread_var_; if unavailable, a default range [0,1) is
596	   * used.
597	   * - Invokes tile_op->Lower(...) with LowerArgs containing target, thread
598	   *   bounds, thread variable, the workspace callback, layout and buffer remap
599	   *   maps, and the list of GEMM-involved buffer vars; the analyzer is passed
600	   *   through for use during lowering.
601	   *
602	   * The lowered statement returned by the operator is then visited by the base
603	   * IRMutatorWithAnalyzer and that result is returned.
604	   *
605	   * @return Stmt The (possibly transformed) statement after lowering or base
606	   * visitor processing.
607	   */
608	  Stmt VisitStmt_(const EvaluateNode *op) final {
609	    const CallNode *call = op->value.as<CallNode>();
610	    // Do not analysis the call node to the global function.
611	    if (call && call->op.as<GlobalVarNode>())
612	      return Downcast<Evaluate>(IRMutatorWithAnalyzer::VisitStmt_(op));
613	
614	    auto tile_op = ParseOperator(tvm::ffi::GetRef<Stmt>(op));
615	    if (!tile_op.defined())
616	      return IRMutatorWithAnalyzer::VisitStmt_(op);
617	    AddWorkspaceCallback callback = [this](int num_elem, DataType dtype) {
618	      auto workspace =
619	          decl_buffer({PrimExpr(num_elem)}, dtype, "workspace", "shared.dyn");
620	      // Record workspace under the innermost block scope so its lifetime
621	      // covers the statements that requested it and does not sink into
622	      // subsequently created inner blocks (e.g., GEMM macro blocks).
623	      if (!workspace_stack_.empty()) {
624	        workspace_stack_.back().push_back(workspace);
625	      } else {
626	        // Fallback: create a temporary frame (should be rare)
627	        workspace_stack_.emplace_back(Array<Buffer>{workspace});
628	      }
629	      return workspace.access_ptr(2); // write
630	    };
631	
632	    Range thread_bounds;
633	
634	    if (analyzer_->const_int_bound.IsBound(thread_var_->var)) {
635	      auto const_int_bound = analyzer_->const_int_bound(thread_var_);
636	      auto min_value = const_int_bound->min_value;
637	      auto max_value = const_int_bound->max_value;
638	      auto extent = max_value + 1 - min_value;
639	      thread_bounds =
640	          Range::FromMinExtent(IntImm(thread_var_->var.dtype(), min_value),
641	                               IntImm(thread_var_->var.dtype(), extent));
642	    } else {
643	      thread_bounds = Range::FromMinExtent(0, 1);
644	    }
645	
646	    // Convert let_bindings_ to Map<Var, PrimExpr> for LowerArgs
647	    Map<Var, PrimExpr> let_var_to_expr;
648	    for (const auto &[var, expr] : let_bindings_) {
649	      let_var_to_expr.Set(var, expr);
650	    }
651	
652	    auto lowered = tile_op->Lower(
653	        LowerArgs{target_, thread_bounds, thread_var_->var, callback,
654	                  layout_map_, buffer_remap_, let_var_to_expr},
655	        analyzer_);
656	    return IRMutatorWithAnalyzer::VisitStmt(lowered);
657	  }
658	
659	  Stmt VisitStmt_(const AttrStmtNode *op) final {
660	    if (op->attr_key == tir::attr::thread_extent) {
661	      IterVar iv = Downcast<IterVar>(op->node);
662	      ICHECK_NE(iv->thread_tag.length(), 0U);
663	      if (iv->thread_tag == "threadIdx.x") {
664	        thread_var_ = iv;
665	        ICHECK(iv->dom->extent.as<IntImmNode>());
666	        thread_block_size_ = iv->dom->extent.as<IntImmNode>()->value;
667	      }
668	    }
669	    return arith::IRMutatorWithAnalyzer::VisitStmt_(op);
670	  }
671	
672	  /**
673	   * @brief Handle a Parallel For node, lowering it based on the layout
674	   * annotation.
675	   *
676	   * This method checks if the For node has a parallel_loop_layout annotation.
677	   * If the For node is a parallel loop (ForKind::kParallel):
678	   * - It must have the parallel_loop_layout annotation, otherwise an error is
679	   *   raised.
680	   * - The loop is partitioned and vectorized based on the annotated layout.
681	   * - If a predicate annotation exists, the loop is wrapped with an IfThenElse.
682	   *
683	   * Special handling for reducers and local buffers:
684	   * - If the loop stores into local buffers, thread partitioning is skipped.
685	   * - If the loop only manipulates local buffers, thread partitioning is
686	   * skipped.
687	   * - If reducers are present, vectorization is skipped.
688	   * - Vectorization is only applied if non-local buffers or vectorizable casts
689	   *   are present.
690	   *
691	   * @return Stmt The lowered statement.
692	   */
693	  Stmt VisitStmt_(const ForNode *op) final {
694	    // Extract reducer info from annotations
695	    Map<Var, ReducerInfo> reducer_info;
696	    if (op->annotations.count(attr::kReducerInfo)) {
697	      reducer_info = op->annotations.Get(attr::kReducerInfo)
698	                         ->as<Map<Var, ReducerInfo>>()
699	                         .value();
700	    }
701	
702	    // First visit the body
703	    For for_node = Downcast<For>(arith::IRMutatorWithAnalyzer::VisitStmt_(op));
704	
705	    // Only process parallel loops
706	    if (op->kind != ForKind::kParallel) {
707	      return for_node;
708	    }
709	
710	    // For nested parallel loops, the annotation is placed on the outermost
711	    // loop. Inner parallel loops without annotation should be skipped here -
712	    // they will be processed as part of the outer loop's partitioning.
713	    if (!op->annotations.count(attr::kParallelLoopLayout)) {
714	      return for_node;
715	    }
716	
717	    auto loop_layout = Downcast<Fragment>(
718	        op->annotations.Get(attr::kParallelLoopLayout).value());
719	
720	    // Get predicate if it exists
721	    Optional<PrimExpr> predicate;
722	    if (op->annotations.count(attr::kParallelLoopPredicate)) {
723	      predicate = Downcast<PrimExpr>(
724	          op->annotations.Get(attr::kParallelLoopPredicate).value());
725	    }
726	
727	    auto root = tvm::ffi::GetRef<For>(op);
728	
729	    // Check if the loop stores into local buffers.
730	    // For example:
731	    //   for i in T.Parallel(1024):
732	    //     A_local[i] = A_global[i]
733	    // Here, A_local is a register-local buffer held independently by each
734	    // thread, so explicit thread binding is not required.
735	    bool store_into_local = false;
736	    PostOrderVisit(root, [&](const ObjectRef &obj) {
737	      if (const auto *store = obj.as<BufferStoreNode>()) {
738	        if (IsLocalBuffer(store->buffer)) {
739	          store_into_local = true;
740	        }
741	      }
742	    });
743	
744	    // Check if the loop only manipulates "local" buffers.
745	    // for i in T.Parallel(1024):
746	    //     A_local[i] = B_local[i]
747	    // This indicates register usage and justifies skipping thread binding.
748	    bool local_register_only = true;
749	    PostOrderVisit(root, [&](const ObjectRef &obj) {
750	      if (const auto *store = obj.as<BufferStoreNode>()) {
751	        if (!IsLocalBuffer(store->buffer)) {
752	          local_register_only = false;
753	        }
754	      } else if (const auto *load = obj.as<BufferLoadNode>()) {
755	        if (!IsLocalBuffer(load->buffer)) {
756	          local_register_only = false;
757	        }
758	      }
759	    });
760	
761	    // Determine if this is a true parallel loop requiring thread partitioning.
762	    // Skip partitioning for loops that only operate on local/register buffers.
763	    bool parallel_loop = !local_register_only && !store_into_local;
764	
765	    // Check if there are non-local buffer accesses (for vectorization decision)
766	    bool has_non_local = false;
767	    PostOrderVisit(for_node->body, [&](const ObjectRef &obj) {
768	      if (const auto *load = obj.as<BufferLoadNode>()) {
769	        if (!IsLocalBuffer(load->buffer) && !IsFragmentBuffer(load->buffer)) {
770	          has_non_local = true;
771	        }
772	      } else if (const auto *store = obj.as<BufferStoreNode>()) {
773	        if (!IsLocalBuffer(store->buffer) && !IsFragmentBuffer(store->buffer)) {
774	          has_non_local = true;
775	        }
776	      }
777	    });
778	
779	    // Check if reducers are present in the loop body
780	    // Workaround: if reducer is presented, don't vectorize loop
781	    // Best solution should be isolate reduction axis out of vectorization
782	    //
783	    // Note: reducer_info stores original buffer data vars, but after visiting
784	    // the body, buffers may have been remapped via var_remap_. We need to find
785	    // the original var to check against reducer_info.
786	    bool has_reducer = false;
787	    PostOrderVisit(for_node->body, [&](const ObjectRef &obj) {
788	      if (!has_reducer) {
789	        if (const auto *store = obj.as<BufferStoreNode>()) {
790	          Var data_var = store->buffer->data;
791	          // Find the original var if it was remapped
792	          // var_remap_ maps old_var -> new_var, so we need reverse lookup
793	          Var original_var = data_var;
794	          for (const auto &[old_var, new_var] : var_remap_) {
795	            if (new_var.same_as(data_var)) {
796	              original_var = old_var;
797	              break;
798	            }
799	          }
800	          has_reducer = reducer_info.count(original_var) != 0;
801	        }
802	      }
803	    });
804	
805	    // Check if vectorizable cast operations exist
806	    bool has_cast_operations = false;
807	    PostOrderVisit(for_node->body, [&](const ObjectRef &obj) {
808	      if (const auto *cast = obj.as<CastNode>()) {
809	        DataType from_ty = cast->value.dtype();
810	        DataType target_ty = cast->dtype;
811	        if (IsCudaVectorizableCast(from_ty, target_ty) &&
812	            TargetIsCuda(Target::Current())) {
813	          has_cast_operations = true;
814	        }
815	      }
816	    });
817	
818	    // Decide whether to vectorize:
819	    // - Only if there are non-local buffers or vectorizable casts
820	    // - AND no reducers are present
821	    bool should_vectorize =
822	        (has_non_local || has_cast_operations) && !has_reducer;
823	
824	    // Lower the parallel loop using the common function
825	    return LowerParallelLoop(for_node, loop_layout, thread_var_->var, analyzer_,
826	                             predicate, parallel_loop, should_vectorize);
827	  }
828	
829	  Target target_;
830	  Map<Var, Buffer> buffer_data_to_buffer_;
831	  Map<Buffer, Layout> layout_map_;
832	  Map<Buffer, Layout> layout_remap_;
833	  Map<Buffer, Buffer> buffer_remap_;
834	  // This is a workaround for cpu backend,
835	  // we need to define a thread_var for the serial loop.
836	  IterVar thread_var_ = IterVar(Range::FromMinExtent(0, 1), Var("v_thread"),
837	                                IterVarType::kDataPar);
838	  size_t thread_block_size_ = 0;
839	  // Stack of per-Block workspace buffers gathered while visiting children
840	  std::vector<Array<Buffer>> workspace_stack_;
841	  // For ptx Node, we need to remap the buffer and indices
842	  // By access CallNode instead of BufferLoad Node.
843	  bool is_ptx_{false};
844	  std::unordered_map<Var, PrimExpr, ObjectPtrHash, ObjectPtrEqual>
845	      let_bindings_;
846	  // Mapping from data Var of a Buffer to Buffer, for lookup
847	  std::unordered_map<Var, Buffer, ObjectPtrHash, ObjectPtrEqual> buffer_map_;
848	  Map<Var, Var> var_remap_;
849	  bool has_tma_{false};
850	};
851	
852	namespace transform {
853	
854	using namespace tir::transform;
855	
856	tvm::transform::Pass LowerTileOp() {
857	  auto pass_func = [=](PrimFunc f, const IRModule &m, const PassContext &ctx) {
858	    return LowerTileOpPass::Substitute(std::move(f));
859	  };
860	  return CreatePrimFuncPass(pass_func, 0, "tl.LowerTileOp", {});
861	}
862	
863	TVM_FFI_STATIC_INIT_BLOCK() {
864	  namespace refl = tvm::ffi::reflection;
865	  refl::GlobalDef().def("tl.transform.LowerTileOp", LowerTileOp);
866	}
867	} // namespace transform
868	
869	} // namespace tl
870	} // namespace tvm
