44	    case 16:
45	      tp = CU_TENSOR_MAP_DATA_TYPE_FLOAT16;
46	      break;
47	    case 8:
48	      tp = CU_TENSOR_MAP_DATA_TYPE_UINT8;
49	      break;
50	    default:
51	      ICHECK(0) << dtype;
52	    }
53	  } else if (dtype.is_bfloat16()) {
54	    tp = CU_TENSOR_MAP_DATA_TYPE_BFLOAT16;
55	  } else if (dtype.is_float8()) {
56	    tp = CU_TENSOR_MAP_DATA_TYPE_UINT8;
57	  } else if (dtype.is_int()) {
58	    switch (dtype.bits()) {
59	    case 64:
60	      tp = CU_TENSOR_MAP_DATA_TYPE_INT64;
61	      break;
62	    case 32:
63	      tp = CU_TENSOR_MAP_DATA_TYPE_INT32;
64	      break;
65	    case 16:
66	      tp = CU_TENSOR_MAP_DATA_TYPE_UINT16;
67	      break;
68	    case 8:
69	      tp = CU_TENSOR_MAP_DATA_TYPE_UINT8;
70	      break;
71	    default:
72	      ICHECK(0) << dtype;
73	    }
74	  } else if (dtype.is_uint()) {
75	    switch (dtype.bits()) {
76	    case 64:
77	      tp = CU_TENSOR_MAP_DATA_TYPE_UINT64;
78	      break;
79	    case 32:
80	      tp = CU_TENSOR_MAP_DATA_TYPE_UINT32;
81	      break;
82	    case 16:
83	      tp = CU_TENSOR_MAP_DATA_TYPE_UINT16;
84	      break;
85	    case 8:
86	      tp = CU_TENSOR_MAP_DATA_TYPE_UINT8;
87	      break;
88	    default:
89	      ICHECK(0) << dtype;
90	    }
91	  } else {
92	    ICHECK(0) << dtype;
93	  }
94	  return static_cast<int>(tp);
95	}
