102	// Constructs a Copy operator node from call arguments and annotations.
103	// args[0]: source region, args[1]: destination region
104	// annotations: Map containing coalesced_width, disable_tma, eviction_policy,
105	// etc.
106	Copy::Copy(Array<PrimExpr> args, Map<String, ObjectRef> annotations) {
107	  ObjectPtr<CopyNode> node = tvm::ffi::make_object<CopyNode>();
108	  Array<Range> rgs[2];
109	  Buffer bf[2];
110	  for (int i = 0; i < 2; i++) {
111	    auto region = NormalizeToBufferRegion(args[i]);
112	    rgs[i] = region->region;
113	    bf[i] = region->buffer;
114	  }
115	  std::tie(node->src, node->dst) = std::tie(bf[0], bf[1]);
116	  std::tie(node->src_range, node->dst_range) = std::tie(rgs[0], rgs[1]);
117	  // Copy annotations from the Call node
118	  node->annotations = annotations;
119	  data_ = std::move(node);
120	}
