131	// Creates iterator variables for dimensions with extent > 1.
132	Array<IterVar> CopyNode::MakeIterVars() const {
133	  // Choose the range set from the lowest-level memory scope between src and
134	  // dst. Scope levels: global < shared/shared.dyn/shared.tmem < local.fragment
135	  // (fragment)
136	  auto scope_level = [](const Buffer &b) -> int {
137	    String s = b.scope();
138	    if (s == "local.fragment" || s == "local")
139	      return 2;
140	    if (s == "shared" || s == "shared.dyn" || s == "shared.tmem")
141	      return 1;
142	    // default to global level for unknown scopes
143	    return 0;
144	  };
145	
146	  int src_level = scope_level(src);
147	  int dst_level = scope_level(dst);
148	  bool base_is_src = (src_level >= dst_level);
149	  const Array<Range> &base_ranges = base_is_src ? src_range : dst_range;
150	
151	  // Sanity check: when switching away from the original (src_range),
152	  // ensure the chosen base ranges are not provably smaller than the original
153	  // per dimension. This guards against generating undersized loop domains.
154	  // Improved logic: use two pointers to traverse both base_ranges and
155	  // src_range, skipping dimensions with extent == 1. The number of non-1
156	  // extents must match.
157	  arith::Analyzer analyzer;
158	
159	  size_t base_dim = 0, src_dim = 0;
160	  while (base_dim < base_ranges.size() && src_dim < src_range.size()) {
161	    // Skip base extents that are 1
162	    while (base_dim < base_ranges.size() &&
163	           is_one(base_ranges[base_dim]->extent)) {
164	      ++base_dim;
165	    }
166	    // Skip src extents that are 1
167	    while (src_dim < src_range.size() && is_one(src_range[src_dim]->extent)) {
168	      ++src_dim;
169	    }
170	    // Both indices now at non-1, or at end
171	    if (base_dim < base_ranges.size() && src_dim < src_range.size()) {
172	      PrimExpr base_ext = base_ranges[base_dim]->extent;
173	      PrimExpr src_ext = src_range[src_dim]->extent;
174	      // Only fail if base extent is provably smaller than src extent
175	      if (analyzer.CanProve(base_ext < src_ext)) {
176	        std::ostringstream oss;
177	        oss << "Selected loop range is smaller than original src range at "
178	               "matched non-1 dimension: "
179	            << "base(extent=" << base_ext
180	            << ", scope=" << (base_is_src ? src.scope() : dst.scope())
181	            << ", min=" << base_ranges[base_dim]->min
182	            << ", base_dim=" << base_dim << ") < src(extent=" << src_ext
183	            << ", min=" << src_range[src_dim]->min << ", src_dim=" << src_dim
184	            << ", scope=" << src.scope() << ") for src=" << src->name
185	            << ", dst=" << dst->name << "\n";
186	        oss << "src buffer: " << src->name << ", scope=" << src.scope() << "\n";
187	        oss << "dst buffer: " << dst->name << ", scope=" << dst.scope() << "\n";
188	        oss << "base_ranges[" << base_dim
189	            << "]: min=" << base_ranges[base_dim]->min
190	            << ", extent=" << base_ext << "\n";
191	        oss << "src_ranges[" << src_dim << "]: min=" << src_range[src_dim]->min
192	            << ", extent=" << src_ext << "\n";
193	        LOG(FATAL) << oss.str();
194	      }
195	      ++base_dim;
196	      ++src_dim;
197	    }
198	  }
199	
200	  // Any remaining unmatched dimensions in either range must all have extent ==
201	  // 1
202	  while (base_dim < base_ranges.size()) {
203	    ICHECK(is_one(base_ranges[base_dim]->extent))
204	        << "base_ranges has extra non-1 extent at dim " << base_dim;
205	    ++base_dim;
206	  }
207	  while (src_dim < src_range.size()) {
208	    ICHECK(is_one(src_range[src_dim]->extent))
209	        << "src_range has extra non-1 extent at dim " << src_dim;
210	    ++src_dim;
211	  }
212	
213	  Array<IterVar> loop_vars;
214	  size_t idx = 0;
215	  for (size_t i = 0; i < base_ranges.size(); i++) {
216	    if (is_one(base_ranges[i]->extent))
217	      continue;
218	    Var var = Var(std::string{char('i' + idx)}, base_ranges[i]->extent->dtype);
219	    idx++;
220	    loop_vars.push_back(
221	        {Range(0, base_ranges[i]->extent), var, IterVarType::kDataPar});
222	  }
223	  return loop_vars;
224	}
