247	// Builds a boundary predicate for memory accesses.
248	// Returns a conjunction of bounds checks, or empty PrimExpr if all checks pass.
249	PrimExpr CopyNode::MakePredicate(arith::Analyzer *analyzer,
250	                                 const Array<IterVar> &ivs,
251	                                 Array<PrimExpr> extents, int src_dst) const {
252	  Array<Range> ranges = src_dst == 0 ? src_range : dst_range;
253	
254	  Array<PrimExpr> cond_list;
255	  ICHECK(extents.size() == ranges.size()) << extents << " " << ranges;
256	  size_t idx = 0;
257	  for (size_t i = 0; i < ranges.size(); i++) {
258	    if (is_one(ranges[i]->extent))
259	      continue;
260	    PrimExpr cond = ranges[i]->min + ivs[idx]->var < extents[i];
261	    if (!analyzer->CanProve(cond, arith::ProofStrength::kSymbolicBound)) {
262	      cond_list.push_back(cond);
263	    }
264	    cond = ranges[i]->min + ivs[idx]->var >= 0;
265	    if (!analyzer->CanProve(cond, arith::ProofStrength::kSymbolicBound)) {
266	      cond_list.push_back(cond);
267	    }
268	    idx++;
269	  }
270	  if (cond_list.empty())
271	    return {};
272	  else {
273	    PrimExpr cond = cond_list[0];
274	    for (size_t i = 1; i < cond_list.size(); i++)
275	      cond = And(cond, cond_list[i]);
276	    return cond;
277	  }
278	}
