685	// Selects the most specific copy instruction for the given target and buffers.
686	// Priority: BulkLoad1D, BulkStore1D, BulkLoad, BulkStore, LDSM, STSM, TMemLoad,
687	// TMemStore, Normal.
688	CopyInst CopyNode::GetCopyInst(Target target, bool disable_tma_lower,
689	                               const LayoutMap &layout_map,
690	                               arith::Analyzer *analyzer,
691	                               bool buffer_oob = false) const {
692	  // disable_tma_lower is from pass_configs
693	  // when tilelang.PassConfigKey.TL_DISABLE_TMA_LOWER is True,
694	  // we will not use tma for bulk load/store
695	
696	  // Check tensor memory operations first (highest priority for SM100/Blackwell)
697	  // 1d tma access can not support out of bound access
698	  if (!disable_tma_lower && !buffer_oob &&
699	      CheckBulkLoad1D(target, layout_map, analyzer)) {
700	    return CopyInst::kBulkLoad1D;
701	  } else if (!disable_tma_lower && !buffer_oob &&
702	             CheckBulkStore1D(target, layout_map, analyzer)) {
703	    return CopyInst::kBulkStore1D;
704	  } else if (!disable_tma_lower && CheckBulkLoad(target, analyzer)) {
705	    return CopyInst::kBulkLoad;
706	  } else if (!disable_tma_lower && CheckBulkStore(target, analyzer)) {
707	    return CopyInst::kBulkStore;
708	  } else if (CheckLDSMCopy(target)) {
709	    return CopyInst::kLDSM;
710	  } else if (CheckSTSMCopy(target)) {
711	    return CopyInst::kSTSM;
712	  } else if (CheckTMemLoad(target)) {
713	    return CopyInst::kTMemLoad;
714	  } else if (CheckTMemStore(target)) {
715	    return CopyInst::kTMemStore;
716	  } else {
717	    return CopyInst::kNormal;
718	  }
719	}
