721	// Lowers the copy operation to PTX code by dispatching to specialized lowering
722	// functions.
723	Stmt CopyNode::Lower(const LowerArgs &T, arith::Analyzer *analyzer) const {
724	  Target target = T.target;
725	
726	  using namespace tvm::transform;
727	  PassContext pass_ctx = PassContext::Current();
728	  bool disable_tma_lower =
729	      pass_ctx->GetConfig<Bool>(kDisableTMALower, Bool(false)).value();
730	  auto copy_inst = GetCopyInst(target, disable_tma_lower || GetDisableTMA(),
731	                               T.layout_map, analyzer);
732	  if (copy_inst == CopyInst::kTMemLoad || copy_inst == CopyInst::kTMemStore) {
733	    auto tmem_copy = LowerTmemCopy(T, analyzer);
734	    ICHECK(tmem_copy.defined()) << "Failed to lower tensor memory copy";
735	    return tmem_copy;
736	  } else if (copy_inst == CopyInst::kBulkLoad1D ||
737	             copy_inst == CopyInst::kBulkStore1D) {
738	    auto bulk_copy = LowerBulkCopy1D(T, analyzer, copy_inst);
739	    ICHECK(bulk_copy.defined()) << "Failed to lower bulk load 1d";
740	    return bulk_copy;
741	  } else if (copy_inst == CopyInst::kBulkLoad ||
742	             copy_inst == CopyInst::kBulkStore) {
743	    auto bulk_copy = LowerBulkCopy(T, analyzer, copy_inst);
744	    ICHECK(bulk_copy.defined()) << "Failed to lower bulk load/store";
745	    return bulk_copy;
746	  } else if (copy_inst == CopyInst::kLDSM || copy_inst == CopyInst::kSTSM) {
747	    auto ldsm_copy = LowerLDSMCopy(T, analyzer, copy_inst);
748	    ICHECK(ldsm_copy.defined()) << "Failed to lower ptx matrix copy";
749	    return ldsm_copy;
750	  } else if (copy_inst == CopyInst::kNormal) {
751	    return LowerNormalCopy(T, analyzer);
752	  } else {
753	    LOG(FATAL) << "Unsupported copy inst " << static_cast<int>(copy_inst);
754	  }
755	}
