757	// Lowers the copy using standard load/store with loop transformations.
758	Stmt CopyNode::LowerNormalCopy(const LowerArgs &T,
759	                               arith::Analyzer *analyzer) const {
760	  bool is_cpu_target = T.target->GetTargetDeviceType() == kDLCPU;
761	  auto simt_loop = MakeSIMTLoop(analyzer);
762	  auto fused_loop = Downcast<For>(ParallelLoopFuser::Fuse(simt_loop));
763	
764	  auto transformed_loop =
765	      Downcast<For>(ParallelLoopTransformer::Substitute(fused_loop));
766	
767	  For vectorized_thread_loop;
768	  auto par_op = ParallelOp(transformed_loop);
769	
770	  if (is_cpu_target || IsLocalBuffer(src) || IsLocalBuffer(dst)) {
771	    if (IsLocalBuffer(src) && !IsLocalBuffer(dst)) {
772	      LOG(WARNING) << "Copy from local buffer `" << src->name << "` to "
773	                   << dst.scope() << " buffer `" << dst->name
774	                   << "` may cause conflicted write.";
775	    }
776	    vectorized_thread_loop = VectorizeLoop(transformed_loop);
777	    return vectorized_thread_loop;
778	  } else {
779	    std::vector<InferLevel> levels = {InferLevel::kCommon, InferLevel::kStrict,
780	                                      InferLevel::kFree};
781	    for (auto level : levels) {
782	      par_op->InferLayout({T.target,
783	                           T.thread_bounds,
784	                           T.layout_map,
785	                           analyzer,
786	                           false,
787	                           T.buffer_remap,
788	                           {}},
789	                          level);
790	    }
791	    auto loop_layout = par_op->GetLoopLayout();
792	    // Use LowerParallelLoop to handle partitioning, vectorization, and
793	    // predicate
794	    return LowerParallelLoop(par_op->GetRoot(), loop_layout, T.thread_var,
795	                             analyzer, par_op->GetPredicate(T.thread_var));
796	  }
797	}
